#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
avmigrate 1.10.0 - single-file build
=======================================

Converts hand-written `azurerm` Terraform resources into Azure Verified Module (AVM)
module blocks, carrying existing configuration across and writing a full changelog.

This file is entirely self-contained:
  * pure Python standard library, no pip install required (Python 3.9+)
  * the AVM module catalogue (153 modules, 3,797 inputs) is embedded,
    so it needs no network access at runtime

Built:          2026-09-07 09:16:17 UTC
Catalog:        2026-09-07T08:53:47Z
Payload SHA256: 87ec32c4bc0b7ffa9a7f284f2c80ed7e

Quick start
-----------
    python avmigrate.py plan  ./infra          # analyse, change nothing
    python avmigrate.py apply ./infra          # rewrite .tf files + changelog
    python avmigrate.py apply ./infra --bump-providers
    python avmigrate.py list                   # supported resource types
    python avmigrate.py explain azurerm_key_vault
    python avmigrate.py info

Always run `plan` first, and keep the generated AVM-MIGRATION-CHANGELOG.md with the
change. `apply` writes a timestamped backup into .avmigrate-backup/ unless you pass
--no-backup.
"""

import base64
import importlib.abc
import importlib.util
import json
import sys
import types
import zlib

if sys.version_info < (3, 9):  # pragma: no cover
    sys.stderr.write("avmigrate requires Python 3.9 or newer\n")
    raise SystemExit(2)

__version__ = '1.10.0'

_PAYLOAD = ""

_BUNDLE = json.loads(zlib.decompress(base64.b64decode(_PAYLOAD)).decode("utf-8"))
_SOURCES = _BUNDLE["sources"]


class _BundleLoader(importlib.abc.Loader):
    """Executes bundled module source out of memory."""

    def __init__(self, fullname):
        self._fullname = fullname

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        source = _SOURCES[self._fullname]
        code = compile(source, f"<avmigrate:{self._fullname}>", "exec")
        exec(code, module.__dict__)


class _BundleFinder(importlib.abc.MetaPathFinder):
    """Resolves `avmigrate.*` imports against the embedded sources."""

    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _SOURCES:
            return None
        is_pkg = fullname == "avmigrate"
        spec = importlib.util.spec_from_loader(
            fullname, _BundleLoader(fullname), is_package=is_pkg
        )
        if is_pkg:
            spec.submodule_search_locations = []
        return spec


if not any(isinstance(f, _BundleFinder) for f in sys.meta_path):
    sys.meta_path.insert(0, _BundleFinder())

# The AVM catalogue travels with the code so the tool works with no network access.
import avmigrate.catalog as _catalog  # noqa: E402

_catalog.EMBEDDED_SCHEMA_B64 = _BUNDLE["schema"]

from avmigrate.cli import main  # noqa: E402


if __name__ == "__main__":
    raise SystemExit(main())
